# ============================================================
# AI Office v1.4 Documentation and Git Checkpoint Installer
# FIXED
# ============================================================
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"

if (-not (Test-Path -LiteralPath $Repository -PathType Container)) {
    throw "AI Office repository not found at $Repository"
}

Set-Location $Repository

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\documentation-backups\" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null

function Write-Base64File {
    param(
        [Parameter(Mandatory=$true)][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$Base64Content
    )

    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination

    if ($Parent -and -not (Test-Path -LiteralPath $Parent -PathType Container)) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath

        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent -PathType Container)) {
            New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null
        }

        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
        Write-Host "[BACKUP ] $RelativePath" -ForegroundColor Yellow
    }

    $Bytes = [Convert]::FromBase64String($Base64Content)
    [IO.File]::WriteAllBytes($Destination, $Bytes)
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}

Write-Base64File -RelativePath "README.md" -Base64Content ""
Write-Base64File -RelativePath "VISION.md" -Base64Content ""
Write-Base64File -RelativePath "ROADMAP.md" -Base64Content ""
Write-Base64File -RelativePath "PROJECT-STATUS.md" -Base64Content ""
Write-Base64File -RelativePath "docs\RESUME-AI-OFFICE-DEVELOPMENT.md" -Base64Content ""
Write-Base64File -RelativePath "config\project-status.json" -Base64Content ""
Write-Base64File -RelativePath "scripts\utilities\Finalize-AIOfficeV14GitCheckpoint.ps1" -Base64Content ""

$VersionPath = Join-Path $Repository "config\identity\version.json"

if (Test-Path -LiteralPath $VersionPath -PathType Leaf) {
    $Version = Get-Content -LiteralPath $VersionPath -Raw | ConvertFrom-Json
    $Version.version = "1.4.0"
    $Version.release_name = "Autonomous Workflows"
    $Version.status = "operational"
    $Version.installed_at = (Get-Date).ToString("o")
    $Version.next_planned_milestone = "1.5 Knowledge Graph and Reasoning"
    $Version | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $VersionPath -Encoding UTF8
    Write-Host "[UPDATED] config\identity\version.json" -ForegroundColor Green
}

$OfficePath = Join-Path $Repository "config\identity\office.json"

if (Test-Path -LiteralPath $OfficePath -PathType Leaf) {
    $Office = Get-Content -LiteralPath $OfficePath -Raw | ConvertFrom-Json
    $Office.version = "1.4.0"
    $Office.codename = "Autonomous Workflows"
    $Office.updated_at = (Get-Date).ToString("o")
    $Office | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $OfficePath -Encoding UTF8
    Write-Host "[UPDATED] config\identity\office.json" -ForegroundColor Green
}

$GitScriptPath = Join-Path $Repository "scripts\utilities\Finalize-AIOfficeV14GitCheckpoint.ps1"
$Tokens = $null
$ParseErrors = $null

[System.Management.Automation.Language.Parser]::ParseFile(
    $GitScriptPath,
    [ref]$Tokens,
    [ref]$ParseErrors
) | Out-Null

if ($ParseErrors.Count -gt 0) {
    throw ("Generated Git checkpoint script contains syntax errors: " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; "))
}

Get-Content -LiteralPath (Join-Path $Repository "config\project-status.json") -Raw | ConvertFrom-Json | Out-Null

Write-Host ""
Write-Host "AI Office documentation updated to v1.4.0." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan
Write-Host ""
Write-Host "Review with:" -ForegroundColor Cyan
Write-Host "git diff -- README.md VISION.md ROADMAP.md PROJECT-STATUS.md"
Write-Host ""
Write-Host "Commit and tag with:" -ForegroundColor Cyan
Write-Host powershell -ExecutionPolicy Bypass -File ".\scripts\utilities\Finalize-AIOfficeV14GitCheckpoint.ps1"
Write-Host ""
Write-Host "Commit, tag, and push with:" -ForegroundColor Cyan
Write-Host powershell -ExecutionPolicy Bypass -File ".\scripts\utilities\Finalize-AIOfficeV14GitCheckpoint.ps1" -Push